                it['pending'] = it['agreed']
            return proposes(it, amount, day)
        if kind == 'too_much':
            if it.get('too_much'):
                return refuse(it)
            it['too_much'] = 'yes'
            day = it['pending'][1] if it['used'] >= 1 else vars.get('attempt1_day')
            if it['used'] == 0:
                it['used'] = 1     # the counter-offer before any attempt is attempt 1 (lesson 4h)
            return offer(it, it['floor'], day, 'The remaining balance stays overdue.')
        if kind == 'vague':
            if it.get('vague'):
                return offer(it, it['pending'][0], it['deadline'])
            it['vague'] = 'yes'
            return 'Which exact day can you pay?'
        if kind == 'stop':
            st['stops'] = int(st.get('stops') or 0) + 1
            if st['stops'] >= 2:
                for x in all_items():
                    if x['status'] == 'open':
                        x['status'], x['note'] = 'noted', 'refused'
