        it['used'] = 1     # 14.5: each next product starts at attempt 1, no second question about today
        return offer(it, it['full'], vars.get('attempt1_day'), 'Now your ' + it['word'] + '.')
    def finish(items, confirmed):
        agreed = [x for x in items if x['status'] == 'agreed']
        if not agreed:
            return 'close_notes'
        if not (confirmed or vars.get('neg_conf') == 'yes'):
            parts = [money(x['agreed'][0]) + ' for your ' + x['word'] + ' on ' + say(iso_day(x['agreed'][1])) for x in agreed]
            text = (st.get('ack', '') + ' To read back: ' + '; '.join(parts) + '. ' + st.get('single_note', '') + ' ' + 'Do you confirm?')
            st['ack'] = ''
            return dict(say=' '.join(text.split()))
        return [dict(product_id=x['id'], amount=x['agreed'][0], date=x['agreed'][1]) for x in agreed]


    import json
    st = json.loads(vars.get('neg_state'))
    items = st['items']
    vars['say_turn'] = 'no'
    reply = str(params.get('reply') or '').strip()
    def speak_line(text):
        text = (reply + ' ' + text).strip()     # the model's answer to a question, then the code's line
        vars['guide'] = 'SAY: "' + text + '"'
        vars['say_now'], vars['say_turn'] = text, 'yes'     # the next node speaks it with fixed text
        asks = [q.strip() + '?' for q in text.split('?')[:-1]]
        if asks:
            st['last_question'] = asks[-1].split('. ')[-1]     # the last question said, to ask again
    answers = params.get('answers') or []
    answers = json.loads(answers) if isinstance(answers, str) else answers
    answers = [answers] if isinstance(answers, dict) else answers
    kinds = [str(a.get('kind') or '') for a in answers]
    unfinished = bool(kinds) and all(k == 'unfinished' for k in kinds)
    done = []
    for a, kind in zip(answers, kinds):
        if kind == 'unfinished':
            continue
        want = str(a.get('item') or '')
        open_items = [x for x in items if x.get('status') == 'open']
        picked = [x for x in open_items if str(x.get('id')) == want]
        it = picked[0] if picked else (open_items or items)[0]
        if it['id'] in done:
            continue                            # one answer per product and message: the first is the main point
        done.append(it['id'])
        amount = a.get('amount')
        amount = float(amount) if str(amount or '').strip() not in ('', 'None') else None
        day = str(a.get('date') or '')[:10]
        line = decide(it, kind, amount, day)
        if line and line == it.get('_said_line') and (amount is not None or day):
            line = decide(it, kind, None, '')   # the day and amount only echo the line said last (round 5 V2: a read-back loop)
        it['line'] = line or ''
        if vars.get('close_key') or vars.get('negotiation_action'):
            break
    if unfinished:
        speak_line('Please go on.' if reply else 'Sorry, please go on.')     # a cut-off message changes nothing
    elif vars.get('close_key') or vars.get('negotiation_action'):
        pass
    else:
        open_items = [x for x in items if x.get('status') == 'open']
        todo = [x for x in open_items if x.get('line')]
